cases.bad:
// public/manifest.json: connect-src chỉ cho phép https → http://localhost:8765 bị CSP block
"content_security_policy": {
  "extension_pages": "... connect-src 'self' https://example.com/"
}

// DevTools: Refused to connect to 'http://localhost:8765/' because it violates the following Content Security Policy directive: "connect-src 'self' https://example.com/"

cases.good:
// public/manifest.json: cho phép cả http: và https: để localhost/LAN IP tùy config user hoạt động
"content_security_policy": {
  "extension_pages": "... connect-src 'self' http: https:"
}

cases.bad:
// AnkiConnect OPTIONS trả Access-Control-Allow-Origin đúng nhưng không có Access-Control-Allow-Methods
await fetch(baseUrl, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify(body)
});
// → CORS preflight failed hoặc 403 vì preflight không pass

cases.good:
// Dùng text/plain để thành 'simple CORS request', tránh preflight; server vẫn parse body JSON
await fetch(baseUrl, {
  method: 'POST',
  headers: { 'Content-Type': 'text/plain' },
  body: JSON.stringify(body)
});
